import React from "react";

export default function RoutePlanner({ tourist, onProceedToSafetyCheck }) {
  return (
    <div
      style={{
        minHeight: "100vh",
        background:
          "linear-gradient(135deg, #FF9E57, #FFD580), url('https://images.unsplash.com/photo-1606925797309-8b5b2e7e7b77?auto=format&fit=crop&w=1500&q=80')",
        backgroundSize: "cover",
        backgroundPosition: "center",
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
        fontFamily: "'Poppins', sans-serif",
      }}
    >
      <div
        style={{
          backgroundColor: "rgba(255,255,255,0.9)",
          padding: "30px 40px",
          borderRadius: 20,
          boxShadow: "0 10px 30px rgba(0,0,0,0.3)",
          textAlign: "center",
          width: 400,
        }}
      >
        <h2 style={{ color: "#3b1f04" }}>🗺️ Route Planner</h2>
        <p>Welcome, <strong>{tourist?.name}</strong>!</p>
        <p>Plan your journey through Varanasi below.</p>

        <button
          onClick={onProceedToSafetyCheck}
          style={{
            backgroundColor: "#ff6f00",
            color: "white",
            border: "none",
            padding: "10px 20px",
            borderRadius: 10,
            marginTop: 20,
            fontWeight: 600,
            cursor: "pointer",
          }}
        >
          ✅ Proceed to Safety Check
        </button>
      </div>
    </div>
  );
}
